"""
    Compute Bezout's coefficients.
    """
def bezout(a: Any, b: Any) -> object {
    (r2, r1) = (a, b);
    (s2, s1) = (1, 0);
    (t2, t1) = (0, 1);
    while (r1 != 0) {
        q = r2 // r1;
        (r2, r1) = (r1, (r2 - (q * r1)));
        (s2, s1) = (s1, (s2 - (q * s1)));
        (t2, t1) = (t1, (t2 - (q * t1)));
    }
    return (s2, t2);
}

"""
    Return the block to which the byte at index i belongs.
    :param block_size: The block size.
    :param i: The index of the interesting byte.
    :return: The index of the block to which the byte at index i belongs.
    """
def ith_byte_block(block_size: int, i: int) -> int {
    assert (block_size > 0);
    assert (i >= 0);
    return (i // block_size);
}

